package vn.edu.hcmute.example3; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig {@Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder();} @Bean UserDetailsService users(UserRepository repo){return login->repo.findByUsernameOrEmail(login,login).map(u->User.withUsername(u.getUsername()).password(u.getPassword()).roles(u.getRole()).disabled(!u.isEnabled()).build()).orElseThrow(()->new UsernameNotFoundException("Không tìm thấy tài khoản"));} @Bean SecurityFilterChain filter(HttpSecurity h)throws Exception{return h.authorizeHttpRequests(a->a.requestMatchers("/login","/register","/verify","/forgot-password","/reset-password","/css/**").permitAll().requestMatchers("/users/**").hasRole("ADMIN").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").usernameParameter("login").defaultSuccessUrl("/products",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout")).build();}}
